spec.setup_code:
var seed = 12345;
function rnd() {
  seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
  var t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
function gauss() {
  var u = Math.max(rnd(), 1e-9), v = rnd();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
var N = 400, pts = [];
var mx = 0, my = 0, i;
for (i = 0; i < N; i++) {
  var cls = i < N / 2 ? 0 : 1;
  var a = Math.PI * rnd();
  var x, y;
  if (cls === 0) { x = Math.cos(a); y = Math.sin(a); }
  else { x = 1 - Math.cos(a); y = 0.5 - Math.sin(a); }
  x += 0.07 * gauss(); y += 0.07 * gauss();
  pts.push({ x: x, y: y, c: cls, ex: gauss(), ey: gauss() });
  mx += x; my += y;
}
mx /= N; my /= N;
var vs = 0;
for (i = 0; i < N; i++) { pts[i].x -= mx; pts[i].y -= my; vs += pts[i].x * pts[i].x + pts[i].y * pts[i].y; }
var sd = Math.sqrt(vs / (2 * N));
for (i = 0; i < N; i++) { pts[i].x /= sd; pts[i].y /= sd; }

var T = 14, SMIN = 0.02, SMAX = 4;
var LR = Math.log(SMAX / SMIN);
var NEU = [61, 95, 145], COL = [[11, 79, 192], [180, 85, 47]];

function ss(x) { x = Math.max(0, Math.min(1, x)); return x * x * (3 - 2 * x); }
function sigmaOf(u) { return SMIN * Math.exp(u * LR) * Math.min(1, u / 0.04); }
function uOf(v) { return Math.log(v / SMIN) / LR; }

function fitText(ctx, s, cx, y, w, color, lh) {
  var size = 13;
  ctx.fillStyle = color; ctx.textAlign = 'center';
  while (size > 11) {
    ctx.font = size + 'px sans-serif';
    if (ctx.measureText(s).width <= w - 16) { ctx.fillText(s, cx, y); return; }
    size--;
  }
  ctx.font = '11px sans-serif';
  if (ctx.measureText(s).width <= w - 16) { ctx.fillText(s, cx, y); return; }
  var mid = Math.floor(s.length / 2), best = -1, k;
  for (k = 0; k < s.length; k++) {
    if (s.charAt(k) === ' ' && (best < 0 || Math.abs(k - mid) < Math.abs(best - mid))) best = k;
  }
  if (best < 0) { ctx.fillText(s, cx, y); return; }
  ctx.fillText(s.slice(0, best), cx, y - lh / 2);
  ctx.fillText(s.slice(best + 1), cx, y + lh / 2);
}

function draw(ctx, width, height, time, dt) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, width, height);
  var w = width, h = height;
  var t = time % T;

  // timeline
  var u, k, cap, phase;
  if (t < 1) { u = 0; k = 1 - ss((t - 0.2) / 0.8); cap = 'data p₀: two interleaved crescents'; phase = 'clean data'; }
  else if (t < 5.5) { u = ss((t - 1) / 4.5); k = 0; cap = 'forward: x_σ = x₀ + σ·ε, the crescents blur into noise'; phase = 'forward process (σ grows, log scale)'; }
  else if (t < 8.5) { u = 1; k = 0; cap = 'only noise is left: p_σ ≈ N(0, σ² I)'; phase = 'frozen at σ_max ≈ 4 × data spread'; }
  else if (t < 13) { u = 1 - ss((t - 8.5) / 4.5); k = 1; cap = 'a denoiser has to learn to walk this back'; phase = 'reverse path (same ε, σ shrinks)'; }
  else { u = 0; k = 1; cap = 'the reverse path ends back at the data p₀'; phase = 'clean data recovered'; }
  var sg = sigmaOf(u);
  var col = k * (1 - ss((sg - 0.35) / 1.0));

  // caption
  fitText(ctx, cap, w / 2, 24, w, '#04204B', 16);

  // layout
  var avail = w - 64;
  var S = Math.max(150, Math.min(avail - 8, h - 118));
  var px = (avail - S) / 2 + 4;
  var py = 56 + (h - 56 - 40 - S) / 2;
  var cx = px + S / 2, cy = py + S / 2;

  // plot frame and guides
  ctx.strokeStyle = '#8098BC'; ctx.lineWidth = 1;
  ctx.globalAlpha = 0.35;
  ctx.beginPath(); ctx.moveTo(px, cy); ctx.lineTo(px + S, cy); ctx.moveTo(cx, py); ctx.lineTo(cx, py + S); ctx.stroke();
  ctx.globalAlpha = 1;
  ctx.strokeRect(px, py, S, S);

  var ext = 2.6 * Math.pow(1 + sg * sg, 0.35);
  var sc = S / 2 / ext;

  ctx.save();
  ctx.beginPath(); ctx.rect(px, py, S, S); ctx.clip();

  // 2-sigma ring of N(0, sigma^2 I)
  if (sg > 0.8) {
    var rr = 2 * Math.sqrt(1 + sg * sg) * sc;
    ctx.globalAlpha = Math.min(1, (sg - 0.8) / 1.2) * 0.8;
    ctx.strokeStyle = '#8098BC'; ctx.setLineDash([4, 4]);
    ctx.beginPath(); ctx.arc(cx, cy, rr, 0, Math.PI * 2); ctx.stroke();
    ctx.setLineDash([]); ctx.globalAlpha = 1;
  }

  var r = S < 260 ? 2.2 : 2.8;
  for (i = 0; i < N; i++) {
    var p = pts[i];
    var X = p.x + sg * p.ex, Y = p.y + sg * p.ey;
    var c = COL[p.c];
    var rc = Math.round(NEU[0] + (c[0] - NEU[0]) * col);
    var gc = Math.round(NEU[1] + (c[1] - NEU[1]) * col);
    var bc = Math.round(NEU[2] + (c[2] - NEU[2]) * col);
    ctx.fillStyle = 'rgba(' + rc + ',' + gc + ',' + bc + ',0.85)';
    ctx.beginPath();
    ctx.arc(cx + X * sc, cy - Y * sc, r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();

  // legend (appears with colour)
  if (col > 0.05) {
    ctx.globalAlpha = col;
    ctx.textAlign = 'left'; ctx.font = '11px sans-serif';
    ctx.fillStyle = '#0B4FC0'; ctx.beginPath(); ctx.arc(px + 12, py + 14, 3.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#3D5F91'; ctx.fillText('upper crescent', px + 21, py + 18);
    ctx.fillStyle = '#B4552F'; ctx.beginPath(); ctx.arc(px + 12, py + 30, 3.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#3D5F91'; ctx.fillText('lower crescent', px + 21, py + 34);
    ctx.globalAlpha = 1;
  }

  // sigma gauge on the right edge
  var gx = w - 22, g0 = 62, g1 = h - 44;
  ctx.textAlign = 'center'; ctx.font = '13px sans-serif'; ctx.fillStyle = '#04204B';
  ctx.fillText('σ', gx, g0 - 14);
  ctx.strokeStyle = '#8098BC'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(gx, g0); ctx.lineTo(gx, g1); ctx.stroke();
  ctx.lineWidth = 1;
  var ticks = [[0, '0'], [0.1, '0.1'], [1, '1'], [4, '4']];
  ctx.font = '11px sans-serif'; ctx.textAlign = 'right';
  for (i = 0; i < ticks.length; i++) {
    var tu = ticks[i][0] === 0 ? 0 : uOf(ticks[i][0]);
    var ty = g1 - tu * (g1 - g0);
    ctx.strokeStyle = '#8098BC';
    ctx.beginPath(); ctx.moveTo(gx - 5, ty); ctx.lineTo(gx + 5, ty); ctx.stroke();
    ctx.fillStyle = '#3D5F91';
    ctx.fillText(ticks[i][1], gx - 8, ty + 4);
  }
  // filled portion + marker
  var my2 = g1 - u * (g1 - g0);
  ctx.strokeStyle = '#B4552F'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(gx, g1); ctx.lineTo(gx, my2); ctx.stroke();
  ctx.lineWidth = 1;
  ctx.fillStyle = '#B4552F';
  ctx.beginPath(); ctx.arc(gx, my2, 5, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = '#ffffff'; ctx.stroke();
  ctx.textAlign = 'right'; ctx.font = '12px sans-serif'; ctx.fillStyle = '#04204B';
  ctx.fillText('σ = ' + sg.toFixed(sg < 1 ? 3 : 2), w - 6, g1 + 20);

  // bottom status line
  fitText(ctx, phase + '  ·  t = ' + t.toFixed(1) + ' s', (w - 64) / 2 + 4, h - 12, w - 64, '#3D5F91', 14);
}

return { draw: draw };
